-- B1.1 Postgres-Board — Schema-Port (P2), SQLite kanban.db -> PostgreSQL
-- Quelle: .schema der Kopie 9c67e857 (06.11.2026), 11 Tabellen / 17 explizite Indizes.
-- Dialekt-Entscheidungen (1:1-treu, konservativ für den Dry-Run):
--   INTEGER                    -> BIGINT        (SQLite-INTEGER ist 64-bit; Epoch-Zeitstempel,
--                                                Zähler, 0/1-Flags bleiben als Ganzzahl —
--                                                keine Semantik-Änderung gegenüber dem Bestand)
--   INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--                                                ("BY DEFAULT" erlaubt explizite ID-Inserts bei
--                                                 der Migration; Sequenz wird danach auf max(id)+1 gesetzt)
--   TEXT / JSON-in-TEXT (payload,result,skills,metadata,...) -> TEXT
--                                                (jsonb wäre eine spätere Optimierung mit App-Anpassung;
--                                                 für den Dry-Run bleibt TEXT, damit Werte bit-genau gleich sind)
-- Trigger: siehe pg_triggers.sql — werden NICHT beim Bulk-Load angewandt (würden Daten mutieren).

BEGIN;

CREATE TABLE tasks (
    id                   TEXT PRIMARY KEY,
    title                TEXT NOT NULL,
    body                 TEXT,
    assignee             TEXT,
    status               TEXT NOT NULL,
    priority             BIGINT DEFAULT 0,
    created_by           TEXT,
    created_at           BIGINT NOT NULL,
    started_at           BIGINT,
    completed_at         BIGINT,
    workspace_kind       TEXT NOT NULL DEFAULT 'scratch',
    workspace_path       TEXT,
    claim_lock           TEXT,
    claim_expires        BIGINT,
    tenant               TEXT,
    result               TEXT,
    idempotency_key      TEXT,
    consecutive_failures BIGINT NOT NULL DEFAULT 0,
    worker_pid           BIGINT,
    last_failure_error   TEXT,
    max_runtime_seconds  BIGINT,
    last_heartbeat_at    BIGINT,
    current_run_id       BIGINT,
    workflow_template_id TEXT,
    current_step_key     TEXT,
    skills               TEXT,
    max_retries          BIGINT,
    branch_name          TEXT,
    project_id           TEXT,
    model_override       TEXT,
    goal_mode            BIGINT NOT NULL DEFAULT 0,
    goal_max_turns       BIGINT,
    session_id           TEXT,
    block_kind           TEXT,
    block_recurrences    BIGINT NOT NULL DEFAULT 0,
    merge_group          TEXT,
    parent_id            TEXT,
    initiative_id        TEXT,
    provider_override    TEXT,
    reasoning_effort     TEXT,
    completion_contract  TEXT,
    worker_started_at    BIGINT,
    family_root_id       TEXT,
    family_order         BIGINT,
    child_role           TEXT NOT NULL DEFAULT 'work',
    repository           TEXT,
    status_changed_at    BIGINT,
    category             TEXT,
    short_description    TEXT
);

CREATE TABLE task_comments (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id    TEXT NOT NULL,
    author     TEXT NOT NULL,
    body       TEXT NOT NULL,
    created_at BIGINT NOT NULL
);

CREATE TABLE task_events (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id    TEXT NOT NULL,
    run_id     BIGINT,
    kind       TEXT NOT NULL,
    payload    TEXT,
    created_at BIGINT NOT NULL
);

CREATE TABLE task_runs (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id             TEXT NOT NULL,
    profile             TEXT,
    step_key            TEXT,
    status              TEXT NOT NULL,
    claim_lock          TEXT,
    claim_expires       BIGINT,
    worker_pid          BIGINT,
    max_runtime_seconds BIGINT,
    last_heartbeat_at   BIGINT,
    started_at          BIGINT NOT NULL,
    ended_at            BIGINT,
    outcome             TEXT,
    summary             TEXT,
    metadata            TEXT,
    error               TEXT,
    worker_started_at   BIGINT
);

CREATE TABLE task_links (
    parent_id TEXT NOT NULL,
    child_id  TEXT NOT NULL,
    PRIMARY KEY (parent_id, child_id)
);

CREATE TABLE kanban_notify_subs (
    task_id            TEXT NOT NULL,
    platform           TEXT NOT NULL,
    chat_id            TEXT NOT NULL,
    thread_id          TEXT NOT NULL DEFAULT '',
    user_id            TEXT,
    created_at         BIGINT NOT NULL,
    last_event_id      BIGINT NOT NULL DEFAULT 0,
    notifier_profile   TEXT,
    last_ping_event_id BIGINT NOT NULL DEFAULT 0,
    delivery_mode      TEXT NOT NULL DEFAULT 'notify',
    chat_type          TEXT,
    user_id_alt        TEXT,
    delivery_metadata  TEXT,
    PRIMARY KEY (task_id, platform, chat_id, thread_id)
);

CREATE TABLE task_attachments (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id      TEXT NOT NULL,
    filename     TEXT NOT NULL,
    stored_path  TEXT NOT NULL,
    content_type TEXT,
    size         BIGINT NOT NULL DEFAULT 0,
    uploaded_by  TEXT,
    created_at   BIGINT NOT NULL
);

CREATE TABLE manager_action_guard (
    task_id          TEXT PRIMARY KEY,
    action_hash      TEXT NOT NULL,
    state_hash       TEXT NOT NULL,
    repeat_count     BIGINT NOT NULL DEFAULT 0,
    halted           BIGINT NOT NULL DEFAULT 0,
    alert_claimed_at BIGINT,
    updated_at       BIGINT NOT NULL
);

-- comment_id ist in SQLite INTEGER PRIMARY KEY OHNE AUTOINCREMENT -> explizite Werte, keine Identity.
CREATE TABLE manager_action_comments (
    comment_id BIGINT PRIMARY KEY,
    task_id    TEXT NOT NULL
);

CREATE TABLE manager_alert_outbox (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id      TEXT NOT NULL,
    action_kind  TEXT NOT NULL,
    repeat_count BIGINT NOT NULL,
    title        TEXT NOT NULL,
    action_hash  TEXT NOT NULL,
    state_hash   TEXT NOT NULL,
    delivered_at BIGINT,
    attempts     BIGINT NOT NULL DEFAULT 0,
    last_error   TEXT,
    created_at   BIGINT NOT NULL,
    UNIQUE (task_id, action_hash, state_hash)
);

-- Explizite Indizes (PK/UNIQUE-Indizes legt PG automatisch an)
CREATE INDEX idx_tasks_assignee_status ON tasks(assignee, status);
CREATE INDEX idx_tasks_status          ON tasks(status);
CREATE INDEX idx_tasks_tenant          ON tasks(tenant);
CREATE INDEX idx_tasks_idempotency     ON tasks(idempotency_key);
CREATE INDEX idx_tasks_session_id      ON tasks(session_id);
CREATE INDEX idx_tasks_parent_id       ON tasks(parent_id);
CREATE INDEX idx_tasks_initiative_id   ON tasks(initiative_id);
CREATE INDEX idx_tasks_family_root     ON tasks(family_root_id, family_order, child_role, status);
CREATE INDEX idx_links_child           ON task_links(child_id);
CREATE INDEX idx_links_parent          ON task_links(parent_id);
CREATE INDEX idx_comments_task         ON task_comments(task_id, created_at);
CREATE INDEX idx_events_task           ON task_events(task_id, created_at);
CREATE INDEX idx_events_run            ON task_events(run_id, id);
CREATE INDEX idx_runs_task             ON task_runs(task_id, started_at);
CREATE INDEX idx_runs_status           ON task_runs(status);
CREATE INDEX idx_notify_task           ON kanban_notify_subs(task_id);
CREATE INDEX idx_attachments_task      ON task_attachments(task_id, created_at);

COMMIT;
